function matchKundli(a, b) {
	const seed = Math.abs(new Date(a.birthDate).getTime() / 864e5 - new Date(b.birthDate).getTime() / 864e5);
	const total = 20 + seed % 15;
	return {
		total: Math.round(total),
		items: [
			["Varna", 1],
			["Vashya", Math.min(2, 1 + seed % 2)],
			["Tara", Math.min(3, 2 + seed % 2)],
			["Yoni", Math.min(4, 2 + seed % 3)],
			["Graha Maitri", Math.min(5, 3 + seed % 3)],
			["Gana", Math.min(6, 3 + seed % 4)],
			["Bhakoot", Math.min(7, 4 + seed % 4)],
			["Nadi", Math.min(8, 5 + seed % 4)]
		].map(([name, score]) => ({
			name,
			score
		}))
	};
}
